  1 | import { useEffect, useRef, useCallback } from "react";
  2 | import type { Track } from "../types";
  3 | import { getCachedAudio, cacheAudioBlob, getCacheMeta } from "./useAudioCache";
  4 | 
  5 | interface AudioEngineCallbacks {
  6 |   onTimeUpdate: (time: number) => void;
  7 |   onDurationChange: (duration: number) => void;
  8 |   onEnded: () => void;
  9 |   onError: (error: string) => void;
 10 |   onLoadStart: () => void;
 11 |   onCanPlay: () => void;
 12 |   onCacheReady?: (trackId: string) => void;
 13 | }
 14 | 
 15 | export function useAudioEngine(callbacks: AudioEngineCallbacks) {
 16 |   const audioRef = useRef<HTMLAudioElement | null>(null);
 17 |   const callbacksRef = useRef(callbacks);
 18 |   const trackUrlRef = useRef<string | null>(null);
 19 |   const currentCacheKeyRef = useRef<string | null>(null);
 20 | 
 21 |   // Keep callbacks ref fresh
 22 |   callbacksRef.current = callbacks;
 23 | 
 24 |   // Initialize audio element once
 25 |   useEffect(() => {
 26 |     const audio = new Audio();
 27 |     audio.preload = "auto";
 28 | 
 29 |     const onTimeUpdate = () => callbacksRef.current.onTimeUpdate(audio.currentTime);
 30 |     const onDurationChange = () => callbacksRef.current.onDurationChange(audio.duration);
 31 |     const onEnded = () => callbacksRef.current.onEnded();
 32 |     const onError = () => {
 33 |       const msg = audio.error
 34 |         ? `Erro de áudio: ${audio.error.message || `código ${audio.error.code}`}`
 35 |         : "Erro desconhecido ao carregar áudio";
 36 |       callbacksRef.current.onError(msg);
 37 |     };
 38 |     const onLoadStart = () => callbacksRef.current.onLoadStart();
 39 |     const onCanPlay = () => callbacksRef.current.onCanPlay();
 40 | 
 41 |     audio.addEventListener("timeupdate", onTimeUpdate);
 42 |     audio.addEventListener("durationchange", onDurationChange);
 43 |     audio.addEventListener("ended", onEnded);
 44 |     audio.addEventListener("error", onError);
 45 |     audio.addEventListener("loadstart", onLoadStart);
 46 |     audio.addEventListener("canplay", onCanPlay);
 47 | 
 48 |     audioRef.current = audio;
 49 | 
 50 |     return () => {
 51 |       audio.removeEventListener("timeupdate", onTimeUpdate);
 52 |       audio.removeEventListener("durationchange", onDurationChange);
 53 |       audio.removeEventListener("ended", onEnded);
 54 |       audio.removeEventListener("error", onError);
 55 |       audio.removeEventListener("loadstart", onLoadStart);
 56 |       audio.removeEventListener("canplay", onCanPlay);
 57 |       audio.pause();
 58 |       audio.src = "";
 59 |       audioRef.current = null;
 60 |     };
 61 |   }, []);
 62 | 
 63 |   const loadTrack = useCallback((track: Track) => {
 64 |     const audio = audioRef.current;
 65 |     if (!audio) return;
 66 | 
 67 |     // Revoke previous blob URL if any
 68 |     if (trackUrlRef.current) {
 69 |       URL.revokeObjectURL(trackUrlRef.current);
 70 |       trackUrlRef.current = null;
 71 |     }
 72 | 
 73 |     const cacheKey = track.driveFileId ? `drive-${track.driveFileId}` : track.id;
 74 |     currentCacheKeyRef.current = cacheKey;
 75 | 
 76 |     // Try loading from cache first
 77 |     getCachedAudio(cacheKey).then((cachedBlob) => {
 78 |       if (cachedBlob && currentCacheKeyRef.current === cacheKey) {
 79 |         const url = URL.createObjectURL(cachedBlob);
 80 |         trackUrlRef.current = url;
 81 |         audio.src = url;
 82 |         audio.load();
 83 |         callbacksRef.current.onCacheReady?.(track.id);
 84 |         return;
 85 |       }
 86 | 
 87 |       // Not cached — load from original source
 88 |       if (track.src) {
 89 |         audio.src = track.src;
 90 |       } else {
 91 |         audio.src = "";
 92 |       }
 93 |       audio.load();
 94 | 
 95 |       // After the audio can play, fetch and cache the data
 96 |       const onCanPlayForCache = async () => {
 97 |         audio.removeEventListener("canplay", onCanPlayForCache);
 98 |         if (currentCacheKeyRef.current !== cacheKey) return;
 99 | 
100 |         try {
101 |           const sourceUrl = track.src || (track.driveFileId ? `/api/drive/stream/${track.driveFileId}` : null);
102 |           if (!sourceUrl) return;
103 | 
104 |           const response = await fetch(sourceUrl);
105 |           if (!response.ok) return;
106 | 
107 |           const blob = await response.blob();
108 |           if (currentCacheKeyRef.current === cacheKey) {
109 |             await cacheAudioBlob(cacheKey, blob, track.title);
110 |           }
111 |         } catch {
112 |           // Silently fail — cache is best-effort
113 |         }
114 |       };
115 | 
116 |       audio.addEventListener("canplay", onCanPlayForCache);
117 |     });
118 |   }, []);
119 | 
120 |   const play = useCallback(() => {
121 |     const audio = audioRef.current;
122 |     if (!audio || !audio.src) return;
123 |     audio.play().catch((err) => {
124 |       callbacksRef.current.onError(`Erro ao reproduzir: ${err.message}`);
125 |     });
126 |   }, []);
127 | 
128 |   const pause = useCallback(() => {
129 |     audioRef.current?.pause();
130 |   }, []);
131 | 
132 |   const stop = useCallback(() => {
133 |     const audio = audioRef.current;
134 |     if (!audio) return;
135 |     audio.pause();
136 |     audio.currentTime = 0;
137 |   }, []);
138 | 
139 |   const seek = useCallback((time: number) => {
140 |     const audio = audioRef.current;
141 |     if (!audio) return;
142 |     audio.currentTime = time;
143 |   }, []);
144 | 
145 |   const setVolume = useCallback((volume: number) => {
146 |     const audio = audioRef.current;
147 |     if (!audio) return;
148 |     audio.volume = volume / 100;
149 |   }, []);
150 | 
151 |   const setPlaybackRate = useCallback((rate: number) => {
152 |     const audio = audioRef.current;
153 |     if (!audio) return;
154 |     audio.playbackRate = rate;
155 |   }, []);
156 | 
157 |   return {
158 |     loadTrack,
159 |     play,
160 |     pause,
161 |     stop,
162 |     seek,
163 |     setVolume,
164 |     setPlaybackRate,
165 |     audioRef,
166 |   };
167 | }
